import{_ as o,I as a,o as n,c as l,b6 as i,j as d,J as r,w as c}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse('{"title":"Desarrollo Practico: Plataforma de Agentes para Planificacion de Viajes Inteligentes","description":"","frontmatter":{},"headers":[],"relativePath":"es-es/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"es-es/stage-2/assignments/travel-planning-agent-platform/index.md"}'),p={name:"es-es/stage-2/assignments/travel-planning-agent-platform/index.md"},u={style:{margin:"32px 0"}};function g(h,e,m,b,f,y){const t=a("StepBar"),s=a("ClientOnly");return n(),l("div",null,[e[0]||(e[0]=i('<h1 id="desarrollo-practico-plataforma-de-agentes-para-planificacion-de-viajes-inteligentes" tabindex="-1">Desarrollo Practico: Plataforma de Agentes para Planificacion de Viajes Inteligentes <a class="header-anchor" href="#desarrollo-practico-plataforma-de-agentes-para-planificacion-de-viajes-inteligentes" aria-label="Permalink to “Desarrollo Practico: Plataforma de Agentes para Planificacion de Viajes Inteligentes”">​</a></h1><h2 id="descripcion-general" tabindex="-1">Descripcion general <a class="header-anchor" href="#descripcion-general" aria-label="Permalink to “Descripcion general”">​</a></h2><p>Este proyecto practico te requiere trabajar con un PRD real para completar desde cero una plataforma de agentes para planificacion de viajes inteligentes. Construiras un producto de IA completo que puede recibir entradas estructuradas, generar itinerarios diarios y soportar guardado y reutilizacion. No es solo un chatbot, sino un producto con capacidades de gestion de tareas.</p><p>Esta es la seccion de practica integral de la Etapa 2. El desafio central de este proyecto radica en como hacer que la IA genere planes de itinerario estructurados y utilizables, en lugar de un largo bloque de texto no accionable.</p><h2 id="conocimientos-previos" tabindex="-1">Conocimientos previos <a class="header-anchor" href="#conocimientos-previos" aria-label="Permalink to “Conocimientos previos”">​</a></h2><p>Antes de comenzar este proyecto, ya deberias dominar lo siguiente:</p><ul><li>Diseno de paginas frontend y uso de bibliotecas de componentes (<a href="./../../frontend/ui-design/">Diseno UI</a>, <a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a>)</li><li>Diseno y desarrollo de interfaces backend (<a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a>)</li><li>Fundamentos de bases de datos y Supabase (<a href="./../../backend/database-supabase/">De la base de datos a Supabase</a>)</li><li>Flujo de trabajo de Git y despliegue (<a href="./../../backend/git-workflow/">Git y GitHub</a>, <a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a>)</li></ul><h2 id="objetivos-de-aprendizaje" tabindex="-1">Objetivos de aprendizaje <a class="header-anchor" href="#objetivos-de-aprendizaje" aria-label="Permalink to “Objetivos de aprendizaje”">​</a></h2><p>Despues de completar esta practica, podras:</p><ol><li>Leer un PRD y extraer la lista de tareas de desarrollo para una plataforma de Agentes</li><li>Disenar formularios de entrada estructurados y formatos de salida estructurados</li><li>Implementar la capa de orquestacion del Agente, procesando entradas de usuario, llamadas a modelos y almacenamiento de resultados</li><li>Construir un ciclo de negocio completo de &quot;generar -&gt; guardar -&gt; reutilizar&quot;</li><li>Completar la integracion de extremo a extremo, entregando un prototipo de producto de IA demostrable</li></ol><h2 id="introduccion-del-proyecto" tabindex="-1">Introduccion del proyecto <a class="header-anchor" href="#introduccion-del-proyecto" aria-label="Permalink to “Introduccion del proyecto”">​</a></h2><p>El producto que vas a construir es una plataforma de agentes para planificacion de viajes inteligentes:</p><table tabindex="0"><thead><tr><th>Funcionalidad</th><th>Descripcion</th></tr></thead><tbody><tr><td><strong>Planificacion de itinerario</strong></td><td>El usuario ingresa origen, destino, fechas, presupuesto y preferencias; el sistema genera el itinerario diario</td></tr><tr><td><strong>Desglose de presupuesto</strong></td><td>Los resultados del itinerario incluyen distribucion de presupuesto y sugerencias</td></tr><tr><td><strong>Gestion de historial</strong></td><td>Los usuarios pueden guardar planes anteriores, regenerar y exportar</td></tr><tr><td><strong>Panel de administracion</strong></td><td>Los administradores consultan destinos populares, tareas fallidas y retroalimentacion de usuarios</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD</p><p>El documento de requisitos de este proyecto esta en GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/es-es/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">Ver PRD</a></p></div>',14)),d("div",u,[r(s,null,{default:c(()=>[r(t,{active:0,items:[{title:"Analisis de requisitos",description:"Leer el PRD, definir paginas, orquestacion del Agente y estructura de entrada/salida"},{title:"Construccion del esqueleto",description:"Usar IA para generar las paginas de inicio, planificacion, historial y administracion"},{title:"Desarrollo iterativo",description:"Agregar salida estructurada, estados de tarea y gestion de historial modulo por modulo"},{title:"Integracion y despliegue",description:"Verificar de extremo a extremo, desplegar y preparar la demostracion"}]})]),_:1})]),e[1]||(e[1]=i(`<h2 id="primera-parte-analisis-de-requisitos" tabindex="-1">Primera parte: Analisis de requisitos <a class="header-anchor" href="#primera-parte-analisis-de-requisitos" aria-label="Permalink to “Primera parte: Analisis de requisitos”">​</a></h2><h3 id="_1-1-leer-el-prd" tabindex="-1">1.1 Leer el PRD <a class="header-anchor" href="#_1-1-leer-el-prd" aria-label="Permalink to “1.1 Leer el PRD”">​</a></h3><p>Abre el documento PRD y responde las siguientes preguntas clave:</p><ul><li>La primera version debe cubrir solo un unico destino?</li><li>La salida del itinerario debe ser estructurada? Cual es la estructura?</li><li>Que tan profunda debe ser la capacidad de exportacion? (enlace para compartir / PDF / imagen)</li><li>Cual es el alcance de las estadisticas del panel y los registros de tareas?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si no tienes respuestas claras a las preguntas anteriores, no comiences a escribir codigo. La comprension inadecuada de los requisitos es la causa mas comun de retrabajo.</p></div><h3 id="_1-2-confirmar-la-arquitectura-del-sistema" tabindex="-1">1.2 Confirmar la arquitectura del sistema <a class="header-anchor" href="#_1-2-confirmar-la-arquitectura-del-sistema" aria-label="Permalink to “1.2 Confirmar la arquitectura del sistema”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;Pagina de planificacion&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;Capa de orquestacion del Agente&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;Llamada al modelo&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;Base de datos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;Planes historicos&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;Estadisticas y logs del panel&quot;]</span></span></code></pre></div><h2 id="segunda-parte-construccion-del-esqueleto-del-proyecto" tabindex="-1">Segunda parte: Construccion del esqueleto del proyecto <a class="header-anchor" href="#segunda-parte-construccion-del-esqueleto-del-proyecto" aria-label="Permalink to “Segunda parte: Construccion del esqueleto del proyecto”">​</a></h2><h3 id="_2-1-generar-paginas-frontend" tabindex="-1">2.1 Generar paginas frontend <a class="header-anchor" href="#_2-1-generar-paginas-frontend" aria-label="Permalink to “2.1 Generar paginas frontend”">​</a></h3><p>Referencia de prompts:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Basandote en el PRD actual, ayudame a generar el esqueleto frontend de una plataforma de agentes para planificacion de viajes inteligentes.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requisitos:</span></span>
<span class="line"><span>1. Paginas incluidas: inicio, planificacion, detalle de itinerario, historial, administracion</span></span>
<span class="line"><span>2. La pagina de planificacion tiene un formulario a la izquierda y una vista previa de resultados a la derecha</span></span>
<span class="line"><span>3. Primero generar solo la estructura de paginas y datos ficticios, sin conectar interfaces reales</span></span>
<span class="line"><span>4. El estilo debe parecerse a un producto de IA moderno</span></span></code></pre></div><h3 id="_2-2-verificar-la-estructura-de-paginas" tabindex="-1">2.2 Verificar la estructura de paginas <a class="header-anchor" href="#_2-2-verificar-la-estructura-de-paginas" aria-label="Permalink to “2.2 Verificar la estructura de paginas”">​</a></h3><p>Verificar item por item:</p><ul><li>[ ] Los campos del formulario de la pagina de planificacion coinciden con el PRD</li><li>[ ] El area de vista previa de resultados puede mostrar datos de itinerario estructurados</li><li>[ ] La pagina de historial puede mostrar multiples planes</li><li>[ ] La pagina del panel de administracion puede mostrar datos estadisticos</li></ul><h2 id="tercera-parte-desarrollo-iterativo" tabindex="-1">Tercera parte: Desarrollo iterativo <a class="header-anchor" href="#tercera-parte-desarrollo-iterativo" aria-label="Permalink to “Tercera parte: Desarrollo iterativo”">​</a></h2><h3 id="_3-1-avanzar-por-modulos" tabindex="-1">3.1 Avanzar por modulos <a class="header-anchor" href="#_3-1-avanzar-por-modulos" aria-label="Permalink to “3.1 Avanzar por modulos”">​</a></h3><ol><li><strong>Autenticacion</strong>: Registro, inicio de sesion</li><li><strong>Formulario de planificacion</strong>: Entrada estructurada (origen, destino, fechas, presupuesto, preferencias)</li><li><strong>Orquestacion del Agente</strong>: Recibir entrada -&gt; Llamar al modelo -&gt; Analizar salida estructurada</li><li><strong>Visualizacion de resultados</strong>: Itinerario por dias, desglose de presupuesto, sugerencias</li><li><strong>Gestion de historial</strong>: Guardar planes, regenerar, exportar</li><li><strong>Panel de administracion</strong>: Destinos populares, tareas fallidas, retroalimentacion de usuarios</li><li><strong>Estados de tarea</strong>: Gestion de estados &quot;generando / exito / error&quot; y registro de errores</li></ol><h3 id="_3-2-autoverificacion-de-modulos" tabindex="-1">3.2 Autoverificacion de modulos <a class="header-anchor" href="#_3-2-autoverificacion-de-modulos" aria-label="Permalink to “3.2 Autoverificacion de modulos”">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificacion</th><th>Metodo de verificacion</th></tr></thead><tbody><tr><td>Completitud de entrada</td><td>Los campos del formulario coinciden con el PRD</td></tr><tr><td>Salida estructurada</td><td>Los resultados del itinerario son datos estructurados (no un bloque de texto)</td></tr><tr><td>Consistencia de datos</td><td>Los datos de trip, itinerary y logs coinciden</td></tr><tr><td>Verificacion de ciclo</td><td>Se puede demostrar &quot;entrada -&gt; generacion -&gt; guardado -&gt; regeneracion&quot;</td></tr></tbody></table><h2 id="cuarta-parte-integracion-y-despliegue" tabindex="-1">Cuarta parte: Integracion y despliegue <a class="header-anchor" href="#cuarta-parte-integracion-y-despliegue" aria-label="Permalink to “Cuarta parte: Integracion y despliegue”">​</a></h2><h3 id="_4-1-pruebas-de-extremo-a-extremo" tabindex="-1">4.1 Pruebas de extremo a extremo <a class="header-anchor" href="#_4-1-pruebas-de-extremo-a-extremo" aria-label="Permalink to “4.1 Pruebas de extremo a extremo”">​</a></h3><p>Verificar al menos los siguientes escenarios:</p><ul><li>Ingresar parametros del itinerario -&gt; Generar itinerario diario -&gt; Ver desglose de presupuesto -&gt; Guardar en historial</li><li>Regenerar itinerario desde el historial</li><li>El administrador consulta estadisticas de tareas y logs de errores</li></ul><h2 id="entregables" tabindex="-1">Entregables <a class="header-anchor" href="#entregables" aria-label="Permalink to “Entregables”">​</a></h2><p>Despues de completar este proyecto, necesitas enviar lo siguiente:</p><ul><li>[ ] Enlace de demostracion en linea accesible</li><li>[ ] Enlace al repositorio de codigo fuente (incluyendo README)</li><li>[ ] Documento PRD</li><li>[ ] Capturas de pantalla de paginas clave (pagina de planificacion, detalle de itinerario, historial, panel de administracion)</li><li>[ ] Video de demostracion de 60 segundos</li></ul><h2 id="criterios-de-evaluacion" tabindex="-1">Criterios de evaluacion <a class="header-anchor" href="#criterios-de-evaluacion" aria-label="Permalink to “Criterios de evaluacion”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Requisitos basicos</th><th>Requisitos avanzados</th></tr></thead><tbody><tr><td>Alineacion con PRD</td><td>Paginas, funcionalidades y estructura de datos basicamente cumplen con el PRD</td><td>Puede explicar claramente las decisiones de diseno</td></tr><tr><td>Ciclo completo del producto</td><td>Planificar -&gt; Guardar -&gt; Historial -&gt; Regenerar funciona completamente</td><td>Soporta exportacion y compartir</td></tr><tr><td>Calidad de salida</td><td>Los resultados del itinerario son estructurados y legibles</td><td>El desglose de presupuesto es razonable, las sugerencias son especificas</td></tr><tr><td>Capacidades del panel</td><td>Las estadisticas de tareas y logs de errores son consultables</td><td>Tiene analisis de destinos populares</td></tr><tr><td>Completitud de ingenieria</td><td>Frontend, backend, base de datos y pipeline de llamadas al modelo conectados</td><td>La gestion de estados de tarea es robusta, los errores son rastreables</td></tr></tbody></table><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to “Referencias”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Diseno UI</a></li><li><a href="./../../frontend/modern-component-library/">Biblioteca de componentes moderna</a></li><li><a href="./../../backend/database-supabase/">De la base de datos a Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Escritura de codigo de interfaces</a></li><li><a href="./../../backend/git-workflow/">Flujo de trabajo de Git y GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Despliegue de aplicaciones web</a></li></ul>`,30))])}const v=o(p,[["render",g]]);export{P as __pageData,v as default};
